    return new Iterator(() => {
      let next = currentIterator.next();
      while (next.done) {
        iterableIndex++;
        if (iterableIndex === this._wrappedIterables.length) {
          return next;
        }
        currentIterator = this._wrappedIterables[iterableIndex].__iterator(
          type,
          reverse
